package com.fakrudeenmart.servlet;
import com.fakrudeenmart.service.ReviewService;
import javax.servlet.http.*; import java.io.IOException;
public class ReviewCreateServlet extends HttpServlet { private ReviewService service; public void init(){service=new ReviewService();} protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{long productId=0;try{productId=ReviewServletSupport.productId(req.getParameter("productId"));service.createReview(ReviewServletSupport.userId(req),productId,ReviewServletSupport.rating(req.getParameter("rating")),req.getParameter("comment"));resp.sendRedirect(ReviewServletSupport.productRedirect(req,productId,"reviewMessage","Your review has been submitted successfully."));}catch(Exception e){if(productId>0)resp.sendRedirect(ReviewServletSupport.productRedirect(req,productId,"reviewError",e instanceof ReviewService.ReviewException?e.getMessage():"Unable to submit your review."));else resp.sendRedirect(req.getContextPath()+"/products");}}}
